Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (51,4,3,'テストの点数を高い順に並べ替えて順位をつけます。1位の人が2人（同点）いた場合、その次の人の順位は、RANK() では「3位」、DENSE_RANK() では「2位」になります。では、1位が3人いた場合の DENSE_RANK() での次の人の順位は何位ですか？','4位','3位','2位',3,'DENSE_RANK は同順位があっても順位を飛ばしません。1位が3人でも次の人は 2位になります。順位を飛ばすのは RANK です（この場合は 4位）。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (52,4,3,'テーブルA、テーブルB、テーブルCの3つを順に LEFT JOIN します。
FROM A LEFT JOIN B ON A.id = B.id LEFT JOIN C ON B.id = C.id
このとき、テーブルBにデータが存在せずNULLになった行は、続くテーブルCとの結合（B.id = C.id）においてどのように扱われますか？','B.id がNULLの行は自動的に無視され、テーブルCとは一切結合されない（結果から消える）。','B.id のNULLと C.id のNULLが「一致する」と判定され、テーブルCのデータと結合される。','B.id がNULLの行も残るが、C.id とは結合できないため、Cの列はすべてNULLとして結果に出力される。',3,'B に一致する行がなく B.id が NULL の行は、B.id = C.id の比較で NULL と C.id が一致しないため、C とは結合されません。LEFT JOIN なので行は残り、C の列は NULL になります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (53,4,3,'Oracle Databaseで、通常の永続表の全行を削除する TRUNCATE TABLE の特徴として正しいものはどれですか？','WHERE で指定した行だけを削除する。','DDLであり、実行後にROLLBACKで削除した行を復元できない。','参照先の親テーブルの全行も自動的に削除する。',2,'Oracleの通常の永続表に対するTRUNCATEはDDLで、ROLLBACKでは行を復元できません。WHEREは指定できず、親表を自動削除する処理でもありません。通常のDELETEより全行削除の負荷を抑えられますが、所要時間は表や環境によります。外部キーなどの制約にも注意が必要です。他のDBMSではトランザクション上の扱いが異なる場合があります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (54,5,1,'2進数の 1011 を10進数で表すと、いくつになりますか？','9','11','13',2,'各桁の重みは右から 1, 2, 4, 8 です。8 + 2 + 1 = 11 になります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (55,5,1,'コンピュータの主記憶として使われ、電源を切ると記憶内容が消える半導体メモリはどれですか？','ROM','RAM','フラッシュメモリ',2,'RAM は揮発性メモリで、電源を切ると内容が消えます。ROM やフラッシュメモリは電源を切っても内容が保持されます。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (56,5,2,'OSI参照モデルで、IPアドレスを用いた経路選択（ルーティング）を担当する層はどれですか？','トランスポート層','ネットワーク層','データリンク層',2,'ネットワーク層（第3層）が IP によるアドレス指定と経路選択を担当します。トランスポート層は TCP/UDP、データリンク層は MAC アドレスによる隣接機器間の転送を担当します。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (57,5,2,'データベースの正規化を行う主な目的として、最も適切なものはどれですか？','データの重複を減らし、更新時の矛盾を防ぐ','検索速度を必ず向上させる','データを暗号化して漏えいを防ぐ',1,'正規化はデータの重複（冗長性）を排除し、更新・追加・削除時の不整合（異常）を防ぐための設計手法です。検索速度の向上や暗号化が目的ではありません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (58,5,3,'平均正常稼働時間（ここではMTBF）が90時間、平均修復時間（MTTR）が10時間のシステムの定常的な稼働率はいくつですか？','80%','90%','99%',2,'平均正常稼働時間を平均正常稼働時間と平均修復時間の合計で割ります。90 / (90 + 10) = 0.9なので90%です。資料によってMTBFに修復時間を含める定義もあるため、この問題では正常に稼働する時間として定義を明示しています。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (59,5,3,'相異なる値が昇順に並ぶ1,024件を通常の二分探索で調べます。両端を含む探索区間の中央（添字の平均の小数部を切り捨て）と探索値を比較し、一致しなければ中央を除いて区間を半分にします。中央の要素を調べる回数は、最悪で何回ですか？','11回','32回','512回',1,'最悪では探索区間の件数が1024、512、256、128、64、32、16、8、4、2、1と変わり、中央を調べる回数は11回です。一般に非空のn件では最大 floor(log2(n)) + 1 回です。ここでは大小と一致の判定をまとめて1回と数えます。計算量がO(log n)であることと、正確な回数は区別します。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (60,5,1,'1バイトは何ビットですか？','4ビット','8ビット','16ビット',2,'1バイトは8ビットです。1ビットは0か1を表し、8ビットでは256通りの値を表せます。符号なし整数として解釈した場合の範囲は0から255です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (61,5,1,'プログラムの命令を解釈して実行する、コンピュータの中心的な装置はどれですか？','CPU','ハードディスク','ディスプレイ',1,'CPU（中央処理装置）は命令の解釈・実行と演算を行う頭脳にあたる装置です。ハードディスクは記憶装置、ディスプレイは出力装置です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (62,5,1,'ファイルの内容を完全に元に戻せる形で、データ量を小さくまとめる処理はどれですか？','可逆圧縮','暗号化','正規化',1,'可逆圧縮は、圧縮前のデータを完全に復元できます。非可逆圧縮では情報の一部を失うため、完全には戻せません。暗号化の主目的は内容の秘匿、データベースの正規化の主目的は冗長性や更新時の不整合を減らすことです。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (63,5,2,'16進数の 1F を10進数で表すと、いくつになりますか？','17','31','63',2,'16進数の F は 10進数の 15 です。1F = 1 × 16 + 15 = 31 になります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (64,5,2,'データ構造のスタックの特徴として正しいものはどれですか？','最後に入れたデータが最初に取り出される（後入れ先出し）','最初に入れたデータが最初に取り出される（先入れ先出し）','好きな位置のデータを自由に取り出せる',1,'スタックは後入れ先出し（LIFO）の構造です。先入れ先出し（FIFO）はキューの特徴です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (65,5,2,'多要素認証の組合せとして適切なものはどれですか？','パスワードと秘密の質問','パスワードと指紋認証','2つの異なるパスワード',2,'多要素認証は「知識（パスワード）」「所持（ICカードなど）」「生体（指紋など）」のうち、異なる種類の要素を組み合わせます。パスワードと秘密の質問、2つのパスワードはどちらも知識情報なので、同じ種類の組合せです。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (66,5,3,'稼働率0.9の装置を2台並列に接続し、どちらか1台が動けばシステムは稼働します。各装置の停止は独立で、切替装置などの故障は考えないとき、システムの稼働率はいくつですか？','81%','99%','90%',2,'両方が同時に停止する確率は、独立という前提で (1 - 0.9) × (1 - 0.9) = 0.01 です。稼働率は 1 - 0.01 = 0.99、つまり99%です。共通原因故障などで停止が独立でない場合には、この式をそのまま適用できません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (67,5,3,'8ビットの2の補数表現で、2進数 11111111 が表す10進数はどれですか？','255','-1','-127',2,'2の補数表現では最上位ビットが符号を表します。11111111 は全ビットを反転して 1 を足すと 00000001 になるので、-1 を表します。符号なし整数として読んだときの 255 とは別です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (1,1,1,'次のうち、Javaで32ビットの符号付き整数を表す基本型はどれですか？','double','int','char',2,'intは32ビットの符号付き整数型です。doubleは64ビットの浮動小数点型です。charも整数型に分類されますが、UTF-16コード単位を表す16ビットの符号なし型なので、この条件には合いません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (2,1,1,'次のうち「繰り返し処理」を行う構文はどれ？','for','case','break',1,'for は繰り返し処理を行う構文です。case は switch 文の分岐、break は繰り返しや switch を途中で抜けるための文です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (3,1,1,'次のうち、Javaのコメントとして正しいものはどれ？','# コメント','// コメント','-- コメント',2,'Java の1行コメントは // で書きます。複数行は /* */ で囲みます。# や -- は Java のコメントではありません（-- は SQL のコメントです）。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (4,1,2,'次のコードの出力として正しいものはどれか。
int x = 5;
{
    int y = x + 2;
    System.out.println(y);
}
System.out.println(x);','5 と 7','7 と 5','エラーになる',2,'変数 y は { } の中でだけ有効で、そこで y = 5 + 2 = 7 を出力します。x は外側で宣言されているので、続く出力は 5 です。よって「7 と 5」になります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (5,1,2,'次のコードの出力として正しいものはどれか。
int x = 10;
int y = 20;
if (x == 10)
    y = 30;
System.out.println(y);','10','20','30',3,'x == 10 は真なので、直後の1文 y = 30 が実行されます。y は 20 から 30 に変わり、30 が出力されます。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (6,1,2,'親クラスの public String name() を子クラスでオーバーライドします。追加の例外は宣言しないとき、正しい宣言はどれですか？','public String name(int id)','public String name()','private String name()',2,'public String name() は同じシグネチャで、アクセスも狭めていないためオーバーライドできます。引数を追加したものはオーバーロードで、privateへの変更はアクセスを狭めるため不可です。参照型の戻り値には共変戻り値も認められるため、常に戻り値の型が完全一致しなければならないわけではありません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (7,1,3,'次のコードの出力として正しいものはどれか。
int a = 3;
int b = 4;
a = b++ + ++a;
System.out.println(a + b);','11','12','13',3,'b++ は現在の値 4 を使ってから b を 5 にします。++a は先に a を 4 にしてから使います。a = 4 + 4 = 8 なので、a + b = 8 + 5 = 13 です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (8,1,3,'次のコードの出力として正しいものはどれか。
int x = 0;
for (int i = 1; i < 4; i++) {
    x += i; if (i == 2) break;
}
System.out.println(x);','1','3','4',2,'i = 1 で x = 1、i = 2 で x = 3 になり、そこで break して繰り返しを抜けます。よって出力は 3 です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (9,1,3,'Java 17のインターフェースに関する説明として正しいものはどれですか？','インターフェースのメソッドはすべてprivateである','1つのクラスは複数のインターフェースを実装できる','インターフェース自身を new で直接インスタンス化できる',2,'1つのクラスで複数のインターフェースを実装できます。インターフェース自身は直接インスタンス化できません。抽象メソッドはpublicですが、Java 17ではdefaultメソッド、staticメソッド、privateメソッドも定義できるため、すべてprivateという説明は誤りです。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (10,2,1,'Spring Bootで、リクエストを受け取るクラスに付けるアノテーションはどれ？','@Controller','@Repository','@Autowired',1,'リクエストを受け取るクラスには @Controller を付けます。@Repository はデータアクセス層、@Autowired は依存性の注入に使います。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (11,2,1,'Controllerから画面に値を渡すためによく使うものはどれ？','Model','Scanner','StringBuilder',1,'Controller から画面へ値を渡すには Model を使い、addAttribute で名前と値を登録します。Scanner は入力用、StringBuilder は文字列連結用です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (12,2,1,'次のコードの説明として正しいものはどれ？
model.addAttribute("empName", employee.getEmpName());','DBに従業員名を保存している','画面で使えるように empName という名前で値を渡している','従業員名を暗号化している',2,'model.addAttribute は、画面（HTML）で使えるように名前を付けて値を渡す処理です。ここでは empName という名前で従業員名を渡しています。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (13,2,2,'Thymeleafで、Controllerから渡された empName を表示する書き方として正しいものはどれ？','<p th:text="${empName}"></p>','<p th:href="${empName}"></p>','<p th:each="${empName}"></p>',1,'Thymeleaf で値を表示するには th:text を使います。th:href は URL 用、th:each は繰り返し用で、用途が異なります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (14,2,2,'次のコードで、BindingResult result を書く位置として正しいものはどれ？
public String login(@Valid @ModelAttribute LoginForm loginForm, BindingResult result, Model model) { return "login"; }','@Valid が付いた引数の直後','モデルModel の前ならどこでもよい','@RequestMapping の前',1,'BindingResultは、検証対象のモデル属性の引数の直後に置きます。検証対象と結果を対応させるためです。位置が離れていると、その検証対象のエラーをこのBindingResultで扱えません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (15,2,2,'return "redirect:/list"; の説明として正しいものはどれ？','list.html を直接表示する','/list に再度リクエストを送る','Modelの中身をすべて保存する',2,'redirect: はブラウザに指定URLへの再リクエストを指示します。テンプレートを直接表示したり、Modelの全内容を保存したりするものではありません。設定によって一部のモデル属性がURLのパラメータになることはあります。リダイレクト後の一時的な通知にはRedirectAttributesのフラッシュ属性を使います。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (16,2,3,'getReferenceById(id) を使ったときに、The given id must not be null が出る原因として考えられるものはどれ？','渡しているidがnullだから','HTMLファイルが存在しないから','@Controllerがないから',1,'The given id must not be null は、getReferenceById などに null の id を渡したときに出るエラーです。画面から id が送られていない、変数名が違うなどを確認します。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (17,2,3,'ログイン成功時に、EntityをそのままSessionに保存するより、Beanに必要な情報だけ詰めて保存する理由として適切なのはどれ？','Entityは必ずSessionに保存できないから','不要な情報やDB管理用の情報まで持ち回らないようにするため','ThymeleafではEntityを表示できないため',2,'Entity をそのままセッションに持たせると、DB 管理用の項目やパスワードなど不要な情報まで持ち回ります。必要な情報だけを Bean に詰めて保存するほうが安全で扱いやすくなります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (18,2,3,'次のコードでキャストが必要な理由として正しいものはどれ？
EmployeeBean user = (EmployeeBean) session.getAttribute("user");','getAttribute() の戻り値が Object 型だから','EmployeeBean はEntityではないから','セッションには文字列しか保存できないから',1,'session.getAttribute() の戻り値は Object 型です。使うには元の型へのキャスト（型変換）が必要になります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (19,3,1,'HTMLでページのタイトルを設定するタグはどれ？','<head>','<title>','<h1>',2,'ページのタイトルは head 内の title タグで設定します。h1 は本文中の見出し、head は title などを含む領域そのものです。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (20,3,1,'HTMLの標準的な画像埋込み要素はどれですか？','<image>','<img>','<pic>',2,'HTMLで画像を埋め込む標準要素はimgです。srcで画像の場所、altで代替テキストを指定します。SVGにはimage要素がありますが、HTMLの標準画像要素とは別です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (21,3,1,'次のうち、正しいリスト構造はどれ？','<ul>
  <li>項目</li>
</ul>','<li>
  <ul>項目</ul>
</li>','<ul>項目</ul>',1,'この単独の箇条書きではulの中にliを置き、その中に項目の文字を書きます。入れ子のリストを作る場合にはliの中にulを置けますが、そのulの項目もliで囲む必要があります。選択肢BとCのようにulの直下へ項目の文字を置く形は不適切です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (22,3,2,'「好きな食べ物」という見出し（h2）と、「ラーメン」「カレー」「寿司」の3つを箇条書き（ul・li）で表示するHTMLとして正しいものを選んでください。','<h2>好きな食べ物</h2>
<ul>
  <li>ラーメン</li>
  <li>カレー</li>
  <li>寿司</li>
</ul>','<h1>好きな食べ物</h1>
<ol>
  <li>ラーメン</li>
  <li>カレー</li>
  <li>寿司</li>
</ol>','<h2>好きな食べ物</h2>
<ul>
  <p>ラーメン</p>
  <p>カレー</p>
  <p>寿司</p>
</ul>',1,'見出しは h2、箇条書きは ul と li の組合せです。ol は番号付きリストなので不適切です。ul の直下に p を置くのも誤りです。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (23,3,2,'「朝のルーティン」という見出し（h2）と、「起きる」「顔を洗う」「朝ごはんを食べる」を番号つきリスト（ol・li）で表示するHTMLとして正しいものを選んでください。','<h2>朝のルーティン</h2>
<ul>
  <li>起きる</li>
  <li>顔を洗う</li>
  <li>朝ごはんを食べる</li>
</ul>','<h2>朝のルーティン</h2>
<ol>
  <p>起きる</p>
  <p>顔を洗う</p>
  <p>朝ごはんを食べる</p>
</ol>','<h2>朝のルーティン</h2>
<ol>
  <li>起きる</li>
  <li>顔を洗う</li>
  <li>朝ごはんを食べる</li>
</ol>',3,'番号付きリストは ol と li の組合せで作ります。ul は番号なしの箇条書きで、ol の直下に p を置くのも誤りです。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (24,3,2,'「Googleで調べる」というテキストのリンクを作成します。リンク先は https://google.com です。正しいHTMLを選んでください。','<link href="https://google.com">
Googleで調べる
</link>','<a href="https://google.com">Googleで調べる</a>','<a src="https://google.com">Googleで調べる</a>',2,'リンクは a タグで作り、リンク先は href 属性で指定します。link タグは CSS などの外部ファイルを読み込むためのもので、a タグに src 属性はありません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (25,3,3,'「名前」「年齢」の2列のテーブルを作り、「【名前】」「15歳」という1行のデータを表示するHTMLとして正しいものを選んでください。','<table><tr><td>名前</td><td>年齢</td></tr><th><td>【名前】</td><td>15歳</td></th></table>','<table><th>名前</th><th>年齢</th><td>【名前】</td><td>15歳</td></table>','<table>
  <tr><th>名前</th><th>年齢</th></tr>
  <tr><td>【名前】</td><td>15歳</td></tr>
</table>',3,'表は table の中に行 tr を置き、見出しのセルは th、データのセルは td で書きます。th や td は必ず tr の中に入れる必要があります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (26,3,3,'「名前を入力してください」というラベルと、テキスト入力欄、「送信」ボタンを作成するHTMLとして正しいものを選んでください。','<form>
  <label for="name">名前を入力してください</label>
  <input type="text" id="name" name="name">
  <button type="submit">送信</button>
</form>','<form><label>名前を入力してください</label><input type="button" id="name"><button>送信</button></form>','<form><p for="name">名前を入力してください</p><text id="name"></text><submit>送信</submit></form>',1,'ラベルは label の for と input の id を対応させ、入力欄は input type="text"、送信は button type="submit" で作ります。text や submit という要素はありません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (27,3,3,'タイトルが「私のページ」、本文に「はじめてのHTMLページです。」という段落を持つ、完全なHTMLファイルとして正しいものを選んでください。','<html><head><h1>私のページ</h1></head><body>はじめてのHTMLページです。</body></html>','<!DOCTYPE html>
<html lang="ja">
  <head>
    <meta charset="UTF-8">
    <title>私のページ</title>
  </head>
  <body>
    <p>はじめてのHTMLページです。</p>
  </body>
</html>','<!DOCTYPE html><html lang="ja"><head><meta charset="UTF-8"></head><body><title>私のページ</title><p>はじめてのHTMLページです。</p></body></html>',2,'選択肢BはDOCTYPE、head内のtitle、body内の段落を適切に配置しています。h1は本文の見出しで、ページタイトルの代わりにはなりません。titleは通常head内に置きます。meta charsetはこの例では文字コードを明示していますが、HTTPヘッダーなどで文字コードが指定される場合もあります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (28,4,1,'"BOOKS"表から書名に"UNIX"を含む行を全て探すために次のSQL文を用いる。aに指定する文字列として、適切なものはどれか。ここで、書名は"BOOKS"表の"書名"列に格納されている。
SELECT * FROM BOOKS WHERE 書名 LIKE ''[a]''','%UNIX','%UNIX%','UNIX%',2,'UNIX を「含む」行を探すには、前後にワイルドカード % を付けた %UNIX% を指定します。%UNIX は末尾が UNIX、UNIX% は先頭が UNIX の行だけにマッチします。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (29,4,1,'”得点”表から、学生ごとに全科目の点数の平均を算出し、平均が80点以上の学生の学生番号とその平均点を求める。aに入れる適切な字句はどれか。
得点（学生番号,科目,点数）
[SQL文] SELECT 学生番号,AVG(点数) FROM 得点 GROUP BY [ a ]','科目 HAVING AVG(点数) >=80','科目 WHERE 点数 >=80','学生番号 HAVING AVG(点数) >=80',3,'学生ごとの平均を求めるので GROUP BY 学生番号 とします。集計結果の条件は WHERE ではなく HAVING で指定するため、HAVING AVG(点数) >= 80 になります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (30,4,1,'埋込みSQLにおいて、問い合わせによって得られた導出表を1行ずつ親プログラムに引き渡す操作がある。この操作と関係の深い字句はどれか。','CURSOR','ORDER BY','UNION',1,'埋込み SQL で、問合せ結果を1行ずつ親プログラムに渡すための仕組みがカーソル（CURSOR）です。ORDER BY は並べ替え、UNION は結果の結合です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (31,4,1,'RDBMS において、特定の利用者だけに表の更新する権限を与える方法として、適切なものはどれか。','CONNECT文で接続を許可する。','CREATE ASSERTION文で表明して制限する。','GRANT文で許可する。',3,'特定の利用者に表への権限を与えるのは GRANT 文です。CONNECT 文は接続のため、CREATE ASSERTION は整合性制約を表明するためのもので、権限付与の手段ではありません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (32,4,1,'表に対するSQLのGRANT文の説明として、適切なものはどれか。','パスワードを設定してデータベースへの接続を制限する。','ビューを作成して、ビューの基となる表のアクセスできる行と列を制限する。','表の利用者に対し、表への問い合わせ、更新、追加、削除などの操作権限を付与する。',3,'GRANT 文は、利用者に対して表への問合せ・更新・追加・削除などの操作権限を付与します。パスワードによる接続制限やビューによる行・列の制限は GRANT 文の説明ではありません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (33,4,1,'Oracle Databaseで、注文明細から注文日ごとに数量の平均を求め、注文日と平均数量を1行ずつ返す正しいSQLはどれですか？','SELECT 注文日,AVG(数量) FROM 注文明細','SELECT 注文日,AVG(数量) FROM 注文明細 GROUP BY 注文日','SELECT 注文日,AVG(SUM(数量)) FROM 注文明細 GROUP BY 注文日',2,'注文日ごとの平均なので、注文日でGROUP BYしてAVG(数量)を求めます。Aは通常列と集計を混在させながらGROUP BYがないため不適切です。Oracleでは集計関数の入れ子自体は可能ですが、CはグループごとのSUMをさらに全体でAVGする形であり、通常列の注文日をこのまま一緒に選べません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (34,4,2,'answer(user_id, is_correct)という練習用テーブルで、is_correctが1の行が2件以上あるuser_idを取得する正しいSQLはどれですか？','SELECT user_id FROM answer WHERE is_correct = 1 AND COUNT(*) >= 2 GROUP BY user_id;','SELECT user_id FROM answer WHERE is_correct = 1 GROUP BY user_id HAVING COUNT(*) >= 2;','SELECT user_id FROM answer GROUP BY user_id HAVING is_correct = 1 AND COUNT(*) >= 2;',2,'WHEREで正解行を絞り、user_idでグループ化した後、HAVING COUNT(*) >= 2で件数を絞ります。COUNT(*)は行数を数えます。WHEREで集計結果を判定するAと、GROUP BYに含めない通常列is_correctをそのままHAVINGで参照するCは不適切です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (35,4,2,'customer（顧客）テーブルに answer（解答）テーブルを LEFT JOIN しました。しかし、「解答していない（answerにデータがない）顧客」も含めて全員を表示したいのに、特定の書き方をすると未解答の顧客が消えてしまいます。全員を表示できる正しいSQLはどれですか？','SELECT * FROM customer c LEFT JOIN answer a ON c.user_id = a.user_id WHERE a.question_id = 1;','SELECT * FROM customer c LEFT JOIN answer a ON c.user_id = a.user_id AND a.question_id = 1;','SELECT * FROM customer c LEFT JOIN answer a ON c.user_id = a.user_id WHERE a.question_id IS NOT NULL;',2,'AのWHERE a.question_id = 1やCのIS NOT NULLは、未一致で右側がNULLになった行を除外します。Bのように右側の条件をONに置けば、条件に合う解答がない顧客も残ります。右側の列を使うWHEREがすべて行を除外するわけではなく、IS NULLなどでは結果が異なります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (36,4,2,'customer テーブルに10行のデータがあります。そのうち nickname 列が NULL（空っぽ）のデータが3行あります。 SELECT COUNT(nickname) FROM customer; を実行した結果、返ってくる数値は何ですか？','10','7','3',2,'COUNT(列名) は、その列が NULL でない行だけを数えます。10行のうち3行が NULL なので 7 になります。すべての行を数えたいときは COUNT(*) を使います。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (37,4,2,'「まだ1度も解答（answerテーブルに記録）していない顧客の user_id」を取得しようとして、以下のSQLを書きました。
SELECT user_id FROM customer WHERE user_id NOT IN (SELECT user_id FROM answer);
もし、answer テーブルの user_id 列にたった1行でも NULL のデータが混ざっていた場合、このSQLの結果はどうなりますか？','NULLの行だけを除外して、正しく未解答の顧客が取得できる。','エラー（ORA-00936など）が発生して実行できない。','結果が「0件（何も返ってこない）」になってしまう。',3,'副問合せにNULLがあると、非一致の顧客でもNOT INはUNKNOWNとなり、一致する顧客ではFALSEになります。どちらもWHEREを通らないので0行です。未解答を探すには相関したNOT EXISTSを使うか、副問合せでNULLを除外する方法があります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (38,4,2,'Oracle Databaseにおいて、customer テーブルの last_name（姓）と first_name（名）の間にスペースを挟んで「山田 太郎」のように結合して取得したいです。正しい書き方はどれですか？','SELECT last_name + '' '' + first_name FROM customer;','SELECT last_name || '' '' || first_name FROM customer;','SELECT CONCAT(last_name, '' '', first_name) FROM customer;',2,'Oracle で文字列を連結するには || 演算子を使います。+ は数値の加算用です。CONCAT は引数を2つしか取れないため、3つ以上を連結するにはこの書き方になりません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (39,4,2,'スコア（score）が高い順にユーザーを並び替えたい（ORDER BY score DESC）のですが、スコアが未入力（NULL）のユーザーがいます。普通に書くと NULL の人が一番上にきてしまいます。「NULLの人は一番下に落とした上で、スコアの高い順に並べる」正しいOracleの書き方はどれですか？','ORDER BY score DESC NULLS LAST','ORDER BY score DESC NULLS FIRST','ORDER BY score DESC WHERE score IS NOT NULL',1,'Oracle では降順のとき NULL が先頭に来ます。NULLS LAST を付けると NULL を末尾にできます。WHERE を ORDER BY の中に書くことはできません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (40,4,2,'questionテーブルから、文章のどの位置でも文字としての%が含まれる行だけを検索したいです。正しいSQLはどれですか？','SELECT * FROM question WHERE question_text LIKE ''%%%'';','SELECT * FROM question WHERE question_text LIKE ''%#_%'' ESCAPE ''#'';','SELECT * FROM question WHERE question_text LIKE ''%#%%'' ESCAPE ''#'';',3,'ESCAPEで指定した#の直後の%は文字として扱われます。パターン%#%%は「任意の前方文字列」「文字としての%」「任意の後方文字列」です。最後のワイルドカードも必要です。Aの%はすべてワイルドカードで、Bは文字としての_を含む行を探す別の条件です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (41,4,2,'次のSQLのように、メインのクエリ（外側）のテーブルの列（c.user_id）を、サブクエリ（内側）の中で参照して比較するような構文のテーブル走査方式を、何サブクエリ（副問合せ）と呼びますか？
SELECT * FROM customer c WHERE EXISTS (SELECT 1 FROM answer a WHERE a.user_id = c.user_id);','スカラー・サブクエリ','相関サブクエリ（相関副問合せ）','表サブクエリ',2,'外側のクエリの列を参照する副問合せを相関副問合せと呼びます。論理的には外側の行に応じて条件を評価しますが、実際の走査方式はオプティマイザの変換などで変わり、必ず行ごとに副問合せを実行するとは限りません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (42,4,2,'練習用の解答データのans_time列を使い、user_idごとに日時の古い順で連番を振ります。同時刻の行同士の順序は問わないとき、SELECT内の正しい記述はどれですか？','ROW_NUMBER() OVER (ORDER BY ans_time PARTITION BY user_id)','ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY ans_time)','RANK() OVER (GROUP BY user_id ORDER BY ans_time)',2,'OVER内ではPARTITION BYでユーザーごとに区切り、ORDER BYで順序を指定します。ROW_NUMBERは各区切りで1から始まる連番を付けます。同時刻の行同士の順序まで固定するには、一意なIDなどを追加のソートキーにします。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (43,4,2,'Oracle Databaseの練習用customer表に、user_id=1の行とnickname列が存在します。ロック待ちのタイムアウト設定や他の障害はないものとします。
メンバーAが UPDATE customer SET nickname = ''ネコ'' WHERE user_id = 1; を実行（まだ COMMIT はしていない）。
その直後、メンバーBが UPDATE customer SET nickname = ''イヌ'' WHERE user_id = 1; を実行しようとした。
このとき、メンバーBの画面（ツール）はどうなりますか？','エラーが表示されて、即座に処理が失敗する。','メンバーAの変更を上書きして、即座に「イヌ」に更新される。','メンバーAが COMMIT または ROLLBACK するまで、処理が一時停止（待機状態）になる。',3,'同じ行の更新に必要なロックをAが保持しているため、Bは解放を待ちます。AのCOMMITまたはROLLBACK後にBの処理が進めます。この問題ではタイムアウトや障害を除外していますが、実際のアプリでは待機中のエラーへの対応も必要です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (44,4,3,'Oracle Databaseの練習用customer表で、時刻を含むDATE型のbirthdayが2000年中の行を検索します。birthdayに通常のB-treeインデックスがあるとき、列を加工せず範囲検索を利用しやすい条件はどれですか？','SELECT * FROM customer WHERE TO_CHAR(birthday, ''YYYY'') = ''2000'';','SELECT * FROM customer WHERE birthday >= DATE ''2000-01-01'' AND birthday < DATE ''2001-01-01'';','SELECT * FROM customer WHERE birthday + 1 > DATE ''2000-01-01'';',2,'列を加工せず、年初以上・翌年初未満の範囲で比較すると通常のインデックスによる範囲検索を利用しやすくなります。翌年初を未満にすることで12月31日の時刻付きデータも含みます。ただし実際にインデックスを使うか、最速になるかは統計情報や件数などを基にオプティマイザが判断します。Aにはファンクション索引など別の設計が考えられます。Cは2000年だけの条件ではありません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (45,4,3,'SQLのEXISTSとINの説明として正しいものはどれですか？','EXISTSは副問合せの結果が1行以上あるかを判定し、INとの速度差は実行計画などに依存する。','EXISTSはどんな表でもINより必ず速い。','INは必ずインデックスを無視して全行走査する。',1,'EXISTSは副問合せの結果の存在を判定します。論理的には1行見つかれば真と分かりますが、実際の処理は結合への変換などの最適化を受けます。INとの速度比較は件数、索引、統計情報、実行計画などに依存し、一方が常に速いとはいえません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (46,4,3,'10,000件の解答データがある answer テーブルがあります。このテーブルを、GROUP BY user_id, question_id のように2つの列を指定してグループ化しました。このSQLを実行した結果、取得できる行数（レコード数）は最大で何行になりますか？','user_id の種類の数（例えばユーザーが50人なら50行）','question_id の種類の数（例えば問題が20問なら20行）','user_id と question_id の「ユニークな組み合わせ」の数（最大10,000行）',3,'複数の列でグループ化すると、その列の値の組合せごとに1行になります。user_id と question_id の組合せの数が上限で、最大でも元の行数の 10,000 行です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (47,4,3,'組織図やカテゴリの親子関係（木構造データ）を1つのSQLで辿りたいとき、Oracle Databaseで伝統的に使われる階層問い合わせ専用の構文（キーワード）はどれですか？','START WITH ... CONNECT BY PRIOR ...','RECURSIVE LOOP ... UNTIL ...','MERGE INTO ... USING ...',1,'Oracle で木構造（階層）を辿る伝統的な構文は START WITH ... CONNECT BY PRIOR ... です。MERGE INTO は更新と挿入をまとめて行う構文です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (48,4,3,'2つのトランザクションが相手の保持するロックの解放を互いに待つデッドロックが起きる典型的な状況はどれですか？','両者が常に同じ順序で2行のロックを取得する。','1つのトランザクションだけがロックを取得し、待ちの循環はない。','一方が行A、他方が行Bをロックした後、それぞれ相手の行のロックを要求する。',3,'一方がAを保持してBを待ち、他方がBを保持してAを待つと、待ちの循環ができます。ロック取得順を統一すると、この典型的な循環を防ぎやすくなります。Oracleはデッドロックを検出してエラーを返すため、永久に停止したままになるとは限りません。アプリ側で適切なロールバックなどが必要です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (49,4,3,'データベースで等価結合を行う際、片方の入力からハッシュ表を作り、もう片方の入力の結合キーを使って照合する方式はどれですか？','ネステッドループ結合（Nested Loop Join）','ソートマージ結合（Sort Merge Join）','ハッシュ結合（Hash Join）',3,'ハッシュ結合は一方からハッシュ表を構築し、他方のキーを照合します。大きな入力の等価結合などで利用されます。メモリに収まらない場合にはディスクを使うこともあり、常に全体がメモリに収まるわけではありません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (50,4,3,'Oracle Databaseで SELECT COUNT(*) FROM answer HAVING COUNT(*) > 5; を実行するとどうなりますか？','GROUP BYがないため必ず構文エラーになる。','全行数が5件より多ければ全行数を1行返し、5件以下なら0行を返す。','行数に関係なく常に0行を返す。',2,'GROUP BYがなくても、この集計問い合わせでは表全体を1グループとして扱い、HAVINGで絞れます。COUNT(*)が5より大きければその件数を1行返します。5以下の場合には値0の行を返すのではなく、結果の行自体がありません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (68,5,3,'SQLインジェクション対策として最も有効なものはどれですか？','プレースホルダ（バインド機構）を用いて SQL を組み立てる','入力できる文字数を制限する','ファイアウォールを設置する',1,'プレースホルダを使うと、入力値が SQL の構文としては解釈されず単なる値として扱われます。文字数制限やファイアウォールだけでは根本的な対策になりません。');
