Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (69,1,1,'Javaで true または false を扱う基本型はどれですか？','boolean','int','String',1,'booleanは真偽値trueとfalseを扱う基本型です。intは整数型、Stringは文字列を表す参照型です。Javaでは整数をそのままifの条件にはできません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (70,1,1,'Javaの配列 int[] values = {10, 20, 30}; で、最初の要素10を参照する式はどれですか？','values[1]','values[0]','values[3]',2,'配列の添字は0から始まります。values[0]は10、values[1]は20です。長さ3の配列でvalues[3]を参照すると範囲外のため例外になります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (71,1,1,'Javaで final int limit = 10; と宣言したローカル変数limitについて、正しい説明はどれですか？','後から limit = 20; と再代入できる','小数だけを代入できる','初期化後は別の値を再代入できない',3,'final変数は一度値を代入すると再代入できません。この例は宣言時に初期化済みです。なおfinalな参照変数の場合、参照先オブジェクトの内容まで常に変更禁止になるわけではありません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (72,1,2,'Javaで次のコードを実行したときの出力はどれですか？
int a = 7;
int b = 2;
System.out.println(a / b);','3','3.5','4',1,'int同士の除算は整数の除算になり、小数部分は0方向へ切り捨てられます。7 / 2は3です。3.5を求めるには、一方をdoubleなどの浮動小数点型にしてから除算します。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (73,1,2,'Javaで次のコードを実行したときの出力はどれですか？
String a = new String("cat");
String b = new String("cat");
System.out.println(a.equals(b));','false','true','コンパイルエラー',2,'Stringのequalsは文字列の内容を比較するので、同じcatならtrueです。この例のaとbは別々のオブジェクトなので、参照の同一性を比べるa == bならfalseになります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (74,1,2,'Javaで次のコードを実行したときの出力はどれですか？
int sum = 0;
for (int value : new int[]{2, 4, 6}) {
    sum += value;
}
System.out.println(sum);','6','10','12',3,'拡張for文で2、4、6を順に取り出し、sumへ加算します。0 + 2 + 4 + 6 = 12なので、出力は12です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (75,1,3,'Javaで次のコードを実行するとどうなりますか？
int x = 0;
if (x != 0 && 10 / x > 1) {
    System.out.println("yes");
} else {
    System.out.println("no");
}','noを出力する','整数の0除算で例外になる','yesを出力する',1,'&&は短絡評価を行います。左辺x != 0がfalseなので右辺10 / xは評価されず、0除算は発生しません。条件はfalseとなり、elseでnoを出力します。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (76,1,3,'Javaで次のコードを実行したとき、表示される順序はどれですか？
try {
    System.out.println("A");
    throw new IllegalArgumentException();
} catch (IllegalArgumentException e) {
    System.out.println("B");
} finally {
    System.out.println("C");
}','A、C','A、B、C','B、C',2,'tryでAを出力した後、投げた例外をcatchが受けてBを出力します。その後finallyでCを出力します。このコードにはプロセス終了などの処理はなく、3つがこの順で表示されます。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (77,1,3,'Javaで、親クラスのインスタンスメソッドを子クラスが正しくオーバーライドしています。親クラス型の変数に子クラスのインスタンスを代入し、そのメソッドを呼ぶと、どの処理が実行されますか？','必ず親クラスの処理','変数の宣言型だけで決まり、子クラスの処理は呼べない','実際のインスタンスに対応する子クラスの処理',3,'オーバーライドされたインスタンスメソッドの呼出しは、実行時のオブジェクトの型に応じて選ばれます。親クラス型の変数でも、子クラスのオブジェクトなら子クラスの実装が呼ばれます。staticメソッドの隠蔽とは区別します。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (78,2,1,'SpringのDI（依存性の注入）の説明として正しいものはどれですか？','必要な依存オブジェクトをコンテナが渡す仕組み','HTMLの画像を圧縮する仕組み','SQLの行を必ず削除する仕組み',1,'DIではオブジェクトが必要とする依存先を外部から渡します。Springのコンテナは管理するBean同士の依存関係を解決して注入します。画像圧縮や行削除とは別の機能です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (79,2,1,'Springで業務ロジックを担当するクラスに付ける代表的なアノテーションはどれですか？','@GetMapping','@Service','@RequestParam',2,'@Serviceはサービス層のクラスを示すステレオタイプで、コンポーネントスキャンの対象になります。@GetMappingはGETのマッピング、@RequestParamはリクエストパラメータの受取りに使います。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (80,2,1,'Spring MVCでHTTPのGETリクエストに対応するメソッドへ付けるアノテーションはどれですか？','@PostMapping','@Entity','@GetMapping',3,'@GetMappingはGETリクエストを処理するメソッドのマッピングです。@PostMappingはPOST用です。@EntityはJPAの永続化対象クラスを示すもので、MVCのGETマッピングではありません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (81,2,2,'Spring MVCで /search?keyword=java のkeywordをメソッド引数として受け取る適切な指定はどれですか？','@RequestParam("keyword") String keyword','@PathVariable("keyword") String keyword','@ResponseBody String keyword',1,'?以降のクエリパラメータは@RequestParamで受け取れます。@PathVariableはURLパスのテンプレート変数用です。@ResponseBodyは主に戻り値をレスポンス本文として扱う指定です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (82,2,2,'Spring MVCの @GetMapping("/users/{id}") で、パスの{id}を整数として受け取る適切な引数はどれですか？','@RequestParam("id") Integer id','@PathVariable("id") Integer id','@Autowired Integer id',2,'パスのテンプレート変数{id}は@PathVariable("id")で受け取ります。Integerへの変換はSpringが行い、整数に変換できない値は通常エラーとなります。@RequestParamはクエリやフォームのパラメータ用です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (83,2,2,'Spring MVCで@Controllerのメソッドに@ResponseBodyを付けてStringを返すと、通常そのStringはどう扱われますか？','常にテンプレート名になる','必ずセッションに保存される','レスポンス本文として書き出される',3,'@ResponseBodyを付けると、戻り値はHTTPメッセージコンバータを通してレスポンス本文へ書き出されます。通常の@Controllerで@ResponseBodyなしのString戻り値はビュー名として扱われるため、違いに注意します。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (84,2,3,'Spring MVCで @Valid @ModelAttribute の直後のBindingResultを使います。result.hasErrors()がtrueのときの、一般的な入力画面の処理として適切なものはどれですか？','保存処理をせず、入力画面と検証エラーを表示する','検証エラーを無視して必ずDBへ保存する','BindingResultをSQL文字列へ連結する',1,'BindingResultで入力検証のエラーを確認し、エラーがあれば保存などの業務処理へ進まず、入力画面を再表示するのが一般的です。検証結果を画面に渡して修正できるようにします。DBへ無条件に保存する処理は不適切です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (85,2,3,'Spring MVCで登録後にredirectし、遷移先で一度表示する成功通知をURLに含めず渡したいとき、適切な方法はどれですか？','通知文をURLのパスへ直接連結する','RedirectAttributes.addFlashAttributeで渡す','必ずEntityの全項目をクエリパラメータにする',2,'addFlashAttributeはリダイレクト先へ一時的な属性を渡します。フラッシュ属性はURLのパラメータとしては露出せず、通常HTTPセッションに一時保存されます。addAttributeによる通常のリダイレクト属性とは用途が異なります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (86,2,3,'Spring Framework 6.0の既定の宣言的トランザクションで、rollbackForやnoRollbackForを指定せず、@Transactionalの対象処理からRuntimeExceptionが外へ伝わった場合、通常どうなりますか？','例外があっても常にコミットする','HTMLだけを再読込みしてDBは必ず保存する','トランザクションをロールバックする',3,'Spring Framework 6.0の既定ではRuntimeExceptionとErrorでロールバックします。チェック例外は既定ではロールバック対象ではありません。rollbackFor、noRollbackForなどを明示すると規則を変更できます。例外を処理の内部で捕捉した場合とは区別します。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (87,3,1,'HTMLで本文の段落を表す要素はどれですか？','<p>','<title>','<meta>',1,'pは本文の段落を表します。titleはページタイトルを指定するメタデータ要素、metaは文字コードなどのメタデータを指定する要素です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (88,3,1,'HTMLで文章中に改行を入れる要素はどれですか？','<hr>','<br>','<head>',2,'brは文章中の改行を表す空要素です。hrは話題の区切りを表し、headは文書のメタデータを置く領域です。段落そのものを区切る場合はpなどを使います。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (89,3,1,'HTMLのimg要素で、画像の代わりになるテキストを指定する属性はどれですか？','href','class','alt',3,'altは画像の代替テキストです。画像が表示できない場合や読み上げなどで使われます。hrefはリンク先、classはスタイルやスクリプトで分類するための属性です。純粋な装飾画像には空のaltを指定することがあります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (90,3,2,'HTMLで <input type="text" id="email" name="email"> にラベルを明示的に関連付ける書き方はどれですか？','<label for="email">メール</label>','<label for="name">メール</label>','<p for="email">メール</p>',1,'labelのforを、対応する入力要素のidと一致させます。この例のidはemailです。nameは送信時の項目名であり、forの対応先ではありません。pのforではラベルの関連付けになりません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (91,3,2,'同じHTMLフォームのラジオボタンで、「Java」と「SQL」のどちらか1つだけを選べるグループを作るには、どの属性を同じ値にしますか？','id','name','value',2,'同じフォームに属するラジオボタンは、同じnameを持つと1つのグループになり、通常1つだけを選択できます。idは各要素を識別するため別々にし、valueは選択した項目を区別するため別の値にします。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (92,3,2,'HTMLで method="get" の検索フォームを通常送信すると、名前付き入力欄の値は主にどこへ入りますか？','画像のalt属性','必ず暗号化されたPOST本文','送信先URLのクエリ文字列',3,'GETフォームの送信では、送信対象の入力項目がURLのクエリ文字列になります。検索条件に向きますが、URLに残るため機密情報の送信には不適切です。HTTPSでもURLの記録や履歴への配慮は必要です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (93,3,3,'HTMLフォームで、name付きのテキスト入力欄に値があります。スクリプトで変更せず通常送信するとき、disabledとreadonlyの違いとして正しいものはどれですか？','disabledの欄は送信されず、readonlyの欄の値は送信される','disabledの欄だけ送信され、readonlyの欄は送信されない','どちらも必ず送信されない',1,'disabledなフォームコントロールは通常の送信データに含まれません。readonlyなテキスト欄は利用者による編集を制限しますが、送信対象になります。どちらもサーバー側の検証や権限チェックの代わりにはなりません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (94,3,3,'HTMLの表で、1つの見出しセルを横方向に2列分広げる指定はどれですか？','<th rowspan="2">見出し</th>','<th colspan="2">見出し</th>','<th spanrows="2">見出し</th>',2,'colspanはセルが占める列数を指定し、2なら横に2列分となります。rowspanは行方向にまたがる指定です。spanrowsは標準的なセル結合属性ではありません。表全体の行と列の整合にも注意します。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (95,3,3,'通常のHTMLフォーム内で、クリックしてもフォーム送信を起こさないボタンを明示する書き方はどれですか？追加のスクリプトはないものとします。','<button type="submit">表示</button>','<button>表示</button>','<button type="button">表示</button>',3,'type="button"はフォーム送信などの既定の動作を持たない通常ボタンです。type="submit"は送信用です。通常のフォーム内でtypeを省略したbuttonは送信ボタンになるため、意図しない送信を避けるにはtypeを明示します。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (96,4,1,'category_id列を持つquestion表から、category_idの重複を除いた値を取得するSQLはどれですか？','SELECT DISTINCT category_id FROM question;','SELECT category_id FROM question ORDER BY category_id;','SELECT category_id FROM question;',1,'DISTINCTは選択した列の値の重複を除きます。ORDER BYは並べ替えであり、重複は除きません。DISTINCTも並び順を保証しないので、順序が必要ならORDER BYを指定します。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (97,4,1,'NULLを含まないscore列を高い順に並べる指定はどれですか？','ORDER BY score ASC','ORDER BY score DESC','GROUP BY score DESC',2,'DESCは降順なので、数値なら大きい値から並びます。ASCは昇順です。GROUP BYは集計用のグループ化で、並べ替え指定の代わりにはなりません。同点の順序まで必要なら追加のキーを指定します。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (98,4,1,'SQLでnickname列がNULLの行を選ぶ正しい条件はどれですか？','WHERE nickname = NULL','WHERE nickname <> NULL','WHERE nickname IS NULL',3,'NULLの判定にはIS NULLを使います。= NULLや<> NULLは通常UNKNOWNとなり、WHEREが求めるTRUEにはならないため、NULL行を正しく取り出せません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (99,4,2,'amount列の値が10、NULL、20の3行だけある表で、SELECT SUM(amount) FROM sales; の結果はどれですか？','30','NULL','3',1,'SUMはNULLを除いた値を合計するので、10 + 20 = 30です。全行がNULL、または行がない場合にはSUMの結果はNULLになります。行数を求めるCOUNT(*)とは別です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (100,4,2,'SQLでCOALESCE(NULL, NULL, 5, 9)の結果はどれですか？','9','5','NULL',2,'COALESCEは左から評価し、最初のNULLでない値を返します。この例では5です。すべてNULLなら結果もNULLです。引数の型が互換である必要があり、この例は整数とNULLだけです。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (101,4,2,'customerにuser_idが1、2の2行、answerにuser_idが1の1行だけあります。customer c INNER JOIN answer a ON c.user_id = a.user_id の結果は何行ですか？','2行','0行','1行',3,'INNER JOINは結合条件が一致する組合せだけを返します。一致するのはuser_idが1の顧客と解答の組だけなので1行です。user_idが2の顧客を残したい場合はLEFT JOINなどを検討します。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (102,4,3,'customer cにanswer aをLEFT JOINして顧客別の解答件数を求めます。a.ans_idは主キーでNULLになりません。未解答の顧客を0件と数える集計式はどれですか？','COUNT(a.ans_id)','COUNT(*)','SUM(1)',1,'未解答でもLEFT JOINは右側の列がNULLの行を1行残します。COUNT(*)とSUM(1)はその行を1と数えますが、COUNT(a.ans_id)はNULLを数えないため0になります。顧客ごとにGROUP BYする前提です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (103,4,3,'SQLでscoreの高い順にROW_NUMBERを振ります。scoreが同点でも順序を一意にしたいとき、user_idが一意かつNULLでないなら適切な指定はどれですか？','ROW_NUMBER() OVER (ORDER BY score DESC)','ROW_NUMBER() OVER (ORDER BY score DESC, user_id ASC)','ROW_NUMBER() OVER (PARTITION BY user_id)',2,'scoreだけでは同点行の順序が決まりません。一意のuser_idを追加のソートキーにすると、同点でも順序を決められます。PARTITION BYは区切りであり、順序の指定ではありません。ROW_NUMBERは同点でも別の番号を付ける点でRANKと異なります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (104,4,3,'同じ1列のSELECT結果が、一方では1、1、2の3行、もう一方では2、3の2行です。2つをUNION ALLで結合したときの行数はどれですか？','3行','4行','5行',3,'UNION ALLは重複を除かず、両方の結果を合わせるので3 + 2 = 5行です。UNIONなら重複が除かれ、値1、2、3の3行になります。どちらもORDER BYなしでは結果の並び順を保証しません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (105,5,1,'論理積ANDで、入力が1と0のときの出力はどれですか？','0','1','入力の順序だけで決まる',1,'ANDは両方の入力が1のときだけ1になります。1と0では片方が0なので出力は0です。どちらかが1なら1になるのはORです。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (106,5,1,'1KiBを1,024バイトとすると、4KiBは何バイトですか？','4,000バイト','4,096バイト','32,768バイト',2,'4 × 1,024 = 4,096バイトです。KiBは2の10乗バイトを表します。32,768はこのデータ量をビットで表した場合の値であり、バイト数ではありません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (107,5,1,'CPUと主記憶の速度差を補うため、頻繁に使うデータなどを一時的に保持する高速な記憶はどれですか？','プリンタ','光ディスク','キャッシュメモリ',3,'キャッシュメモリは主記憶より高速で、利用する可能性の高いデータや命令を保持して主記憶へのアクセスを減らします。プリンタは出力装置、光ディスクは補助記憶媒体です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (108,5,2,'空のキューにA、B、Cの順で追加し、1回取り出します。取り出されるものはどれですか？','A','C','必ずランダムに選ばれる',1,'通常のキューは先入れ先出しFIFOなので、最初に追加したAから取り出します。最後に追加したCから取り出すのは、スタックの後入れ先出しLIFOです。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (109,5,2,'DNSの基本的な役割として適切なものはどれですか？','画像ファイルの画質を上げる','ドメイン名に対応するIPアドレスなどの情報を問い合わせる','すべての通信内容を必ず暗号化する',2,'DNSは階層的な名前システムで、ドメイン名からIPアドレスなどのレコード情報を得るために使います。画像処理や通信内容の暗号化を行う機能そのものではありません。IPアドレス以外の情報を持つレコードもあります。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (110,5,2,'1回目のテストは20問中15問正解、2回目は10問中9問正解でした。2回を合わせた全問題の正答率は何%ですか？','82.5%','75%','80%',3,'全正解数は15 + 9 = 24、全問題数は20 + 10 = 30です。24 / 30 × 100 = 80%になります。各回の率75%と90%を単純平均した82.5%は、問題数が異なる場合の全問題の正答率にはなりません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (111,5,3,'IPv4の通常の/26サブネットで、ネットワークアドレスとブロードキャストアドレスを除くと、ホストへ割り当てられるアドレスはいくつですか？','62個','64個','30個',1,'IPv4は32ビットで、/26ではホスト部が6ビットです。2の6乗で64個のアドレスがあり、ネットワークとブロードキャストの2個を除いて62個です。/31のポイントツーポイントなどの例外は、この/26の条件には当たりません。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (112,5,3,'8ビットの2の補数で表せる符号付き整数の範囲はどれですか？','-127から127','-128から127','0から255',2,'nビットの2の補数表現の範囲は -2の(n-1)乗から2の(n-1)乗 - 1です。8ビットでは-128から127です。0から255は8ビットの符号なし整数の範囲です。');
Insert into PROSTA_USER.QUESTION (QUESTION_ID,CATEGORY_ID,DIFFICULTY,QUESTION_TEXT,OPTION_A,OPTION_B,OPTION_C,CORRECT_OPTION,EXPLANATION) values (113,5,3,'稼働率0.9と0.8の装置を直列に使い、両方が動作したときだけシステムが稼働します。停止が独立で、他の故障を考えないとき、システムの稼働率はいくつですか？','98%','85%','72%',3,'独立な装置の直列システムでは、両方が動作する確率を掛けます。0.9 × 0.8 = 0.72なので72%です。どちらかが動けばよい並列構成の式とは異なります。');
