--  学習機能拡張 (2026-11-02): 再構築時の新規オブジェクト
--  増分SQLは廃止。直前バックアップのデータ差分を確認してから再構築する。
--------------------------------------------------------
ALTER TABLE study_plan ADD (
    category_id NUMBER(10),
    target_question_count NUMBER(2) DEFAULT 10 NOT NULL
);
ALTER TABLE study_plan ADD CONSTRAINT fk_study_plan_category
    FOREIGN KEY (category_id) REFERENCES category (category_id);
ALTER TABLE study_plan ADD CONSTRAINT ck_study_plan_target_count
    CHECK (target_question_count IN (5, 10, 15));

CREATE SEQUENCE seq_question_note START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9999999999;
CREATE TABLE question_note (
    note_id NUMBER(10) NOT NULL,
    user_id NUMBER(10) NOT NULL,
    question_id NUMBER(10) NOT NULL,
    content VARCHAR2(1000 CHAR) NOT NULL,
    created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_question_note PRIMARY KEY (note_id),
    CONSTRAINT uq_question_note_user_question UNIQUE (user_id, question_id),
    CONSTRAINT fk_question_note_user FOREIGN KEY (user_id) REFERENCES customer (user_id) ON DELETE CASCADE,
    CONSTRAINT fk_question_note_question FOREIGN KEY (question_id) REFERENCES question (question_id) ON DELETE CASCADE
);
CREATE INDEX ix_question_note_question ON question_note (question_id);
COMMENT ON TABLE question_note IS '学習メモ(問題ごと・本人のみ閲覧)';

CREATE SEQUENCE seq_question_report START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9999999999;
CREATE TABLE question_report (
    report_id NUMBER(10) NOT NULL,
    user_id NUMBER(10) NOT NULL,
    question_id NUMBER(10) NOT NULL,
    reason VARCHAR2(30) NOT NULL,
    detail VARCHAR2(1000 CHAR),
    status VARCHAR2(20) DEFAULT 'OPEN' NOT NULL,
    created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_question_report PRIMARY KEY (report_id),
    CONSTRAINT ck_question_report_reason CHECK (reason IN ('WRONG_ANSWER', 'UNCLEAR_EXPLANATION', 'OTHER')),
    CONSTRAINT ck_question_report_status CHECK (status IN ('OPEN', 'RESOLVED', 'ON_HOLD')),
    CONSTRAINT fk_question_report_user FOREIGN KEY (user_id) REFERENCES customer (user_id) ON DELETE CASCADE,
    CONSTRAINT fk_question_report_question FOREIGN KEY (question_id) REFERENCES question (question_id) ON DELETE CASCADE
);
CREATE INDEX ix_qreport_status_created ON question_report (status, created_at);
CREATE INDEX ix_qreport_user_question ON question_report (user_id, question_id);
CREATE INDEX ix_question_report_question ON question_report (question_id);
COMMENT ON TABLE question_report IS '問題・解説の報告';

CREATE SEQUENCE seq_friend_challenge START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9999999999;
CREATE SEQUENCE seq_friend_challenge_question START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9999999999;
CREATE SEQUENCE seq_friend_challenge_participant START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9999999999;
CREATE SEQUENCE seq_friend_challenge_answer START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9999999999;
CREATE TABLE friend_challenge (
    challenge_id NUMBER(10) NOT NULL,
    creator_id NUMBER(5) NOT NULL,
    opponent_id NUMBER(5) NOT NULL,
    category_id NUMBER(10) NOT NULL,
    category_name VARCHAR2(100 CHAR) NOT NULL,
    difficulty NUMBER(1) NOT NULL,
    question_count NUMBER(2) NOT NULL,
    created_at TIMESTAMP NOT NULL,
    CONSTRAINT pk_friend_challenge PRIMARY KEY (challenge_id),
    CONSTRAINT ck_friend_challenge_users CHECK (creator_id <> opponent_id),
    CONSTRAINT ck_friend_challenge_difficulty CHECK (difficulty BETWEEN 1 AND 3),
    CONSTRAINT ck_friend_challenge_count CHECK (question_count IN (5, 10, 15)),
    CONSTRAINT fk_friend_challenge_creator FOREIGN KEY (creator_id) REFERENCES customer (user_id),
    CONSTRAINT fk_friend_challenge_opponent FOREIGN KEY (opponent_id) REFERENCES customer (user_id)
);
CREATE TABLE friend_challenge_question (
    challenge_question_id NUMBER(10) NOT NULL,
    challenge_id NUMBER(10) NOT NULL,
    question_order NUMBER(2) NOT NULL,
    question_id NUMBER(10) NOT NULL,
    question_text VARCHAR2(1000 CHAR) NOT NULL,
    option_a VARCHAR2(300 CHAR) NOT NULL,
    option_b VARCHAR2(300 CHAR) NOT NULL,
    option_c VARCHAR2(300 CHAR) NOT NULL,
    correct_option NUMBER(1) NOT NULL,
    explanation VARCHAR2(2000 CHAR),
    CONSTRAINT pk_friend_challenge_question PRIMARY KEY (challenge_question_id),
    CONSTRAINT uk_friend_challenge_question_pos UNIQUE (challenge_id, question_order),
    CONSTRAINT ck_friend_challenge_q_correct CHECK (correct_option BETWEEN 1 AND 3),
    CONSTRAINT fk_friend_challenge_q_challenge FOREIGN KEY (challenge_id) REFERENCES friend_challenge (challenge_id)
);
CREATE TABLE friend_challenge_participant (
    participant_id NUMBER(10) NOT NULL,
    challenge_id NUMBER(10) NOT NULL,
    user_id NUMBER(5) NOT NULL,
    correct_count NUMBER(2),
    submitted_at TIMESTAMP,
    CONSTRAINT pk_friend_challenge_participant PRIMARY KEY (participant_id),
    CONSTRAINT uk_friend_challenge_participant UNIQUE (challenge_id, user_id),
    CONSTRAINT ck_friend_challenge_p_submit
        CHECK ((correct_count IS NULL AND submitted_at IS NULL)
            OR (correct_count IS NOT NULL AND submitted_at IS NOT NULL)),
    CONSTRAINT fk_friend_challenge_p_challenge FOREIGN KEY (challenge_id) REFERENCES friend_challenge (challenge_id),
    CONSTRAINT fk_friend_challenge_p_user FOREIGN KEY (user_id) REFERENCES customer (user_id)
);
CREATE TABLE friend_challenge_answer (
    challenge_answer_id NUMBER(10) NOT NULL,
    participant_id NUMBER(10) NOT NULL,
    challenge_question_id NUMBER(10) NOT NULL,
    ans_option NUMBER(1) NOT NULL,
    correct_flag NUMBER(1) NOT NULL,
    CONSTRAINT pk_friend_challenge_answer PRIMARY KEY (challenge_answer_id),
    CONSTRAINT uk_friend_challenge_answer UNIQUE (participant_id, challenge_question_id),
    CONSTRAINT ck_friend_challenge_a_option CHECK (ans_option BETWEEN 1 AND 4),
    CONSTRAINT ck_friend_challenge_a_flag CHECK (correct_flag IN (0, 1)),
    CONSTRAINT fk_friend_challenge_a_part FOREIGN KEY (participant_id) REFERENCES friend_challenge_participant (participant_id),
    CONSTRAINT fk_friend_challenge_a_question FOREIGN KEY (challenge_question_id) REFERENCES friend_challenge_question (challenge_question_id)
);
CREATE INDEX ix_friend_challenge_p_user ON friend_challenge_participant (user_id);
CREATE INDEX ix_friend_challenge_creator ON friend_challenge (creator_id);
CREATE INDEX ix_friend_challenge_opponent ON friend_challenge (opponent_id);
COMMENT ON TABLE friend_challenge IS '非同期フレンド対戦';
COMMENT ON TABLE friend_challenge_question IS 'フレンド対戦の固定問題スナップショット';
COMMENT ON TABLE friend_challenge_participant IS 'フレンド対戦の参加者と提出結果';
COMMENT ON TABLE friend_challenge_answer IS 'フレンド対戦の解答';
COMMENT ON COLUMN friend_challenge_question.question_id IS '元問題削除後も結果を残すためFKなし';

COMMIT;
